package cn.sixnine.filmlog;

import android.app.*;
import android.content.*;
import android.content.res.Configuration;
import android.database.sqlite.SQLiteDatabase;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;

/** Real activities and transactions, only in the explicitly authorized isolated test package. */
public final class LibraryPagesInstrumentation extends Instrumentation {
    interface Action{void run()throws Exception;}
    private Activity activity;private LogStore logs;private Configuration original;private String owner,other,camera,batch,scanId,referenceId;private final ArrayList<String> shots=new ArrayList<>();private int assertions;
    private void check(boolean b,String s){assertions++;if(!b)throw new AssertionError(s);}
    private void main(Action action)throws Exception{Throwable[] error={null};runOnMainSync(()->{try{action.run();}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new RuntimeException(error[0]);}
    private Object field(Object object,String key)throws Exception{java.lang.reflect.Field f=object.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(object);}
    private void set(Object object,String key,Object value)throws Exception{java.lang.reflect.Field f=object.getClass().getDeclaredField(key);f.setAccessible(true);f.set(object,value);}
    private Object call(Object object,String name,Class<?>[] types,Object... args)throws Exception{java.lang.reflect.Method m=object.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(object,args);}
    private void call(String method)throws Exception{call(activity,method,new Class<?>[]{});}
    private View root(){return ((ViewGroup)activity.findViewById(android.R.id.content)).getChildAt(0);}
    private View tag(String tag){View v=root().findViewWithTag(tag);check(v!=null,"tag "+tag);return v;}
    private Dialog sheet()throws Exception{return (Dialog)field(activity,activity instanceof MainActivity?"rollSheet":"librarySheet");}
    private Button button(View view,String text){if(view instanceof Button&&((Button)view).getText().toString().equals(text))return (Button)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){Button b=button(((ViewGroup)view).getChildAt(i),text);if(b!=null)return b;}return null;}
    private void snap(String name)throws Exception{waitForIdleSync();SystemClock.sleep(250);Bitmap b=getUiAutomation().takeScreenshot();check(b!=null,"native screenshot");File folder=new File(getTargetContext().getFilesDir(),"library-page-shots");folder.mkdirs();try(OutputStream out=new FileOutputStream(new File(folder,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    private Activity start(Class<?> type,Intent intent)throws Exception{if(activity!=null){main(()->{if(original!=null)activity.getResources().updateConfiguration(original,activity.getResources().getDisplayMetrics());activity.finish();});}activity=startActivitySync(intent.setClass(getTargetContext(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();original=new Configuration(activity.getResources().getConfiguration());return activity;}
    private File jpeg(Context context,String token,int color)throws Exception{File dir=new File(context.getFilesDir(),"scans");dir.mkdirs();File file=new File(dir,token+".jpg");Bitmap b=Bitmap.createBitmap(90,60,Bitmap.Config.ARGB_8888);b.eraseColor(color);try(OutputStream out=new FileOutputStream(file)){b.compress(Bitmap.CompressFormat.JPEG,90,out);}b.recycle();return file;}
    private void fixture(Context c)throws Exception{logs=new LogStore(c);CatalogStore cat=new CatalogStore(logs);camera=cat.saveEntry("","camera","Nikon FE2","35 mm","");cat.saveCamera(camera,"Nikon FE2","","35 mm","","",false,CameraLogos.suggest(c,"Nikon FE2"));cat.saveEntry("","camera","Olympus 35 DC","35 mm","");owner=cat.manual(UUID.randomUUID().toString(),"Native library test","Kodak Ultramax 400","Nikon FE2",400,36,"35 mm",camera,"","original:kodak_ultramax_400");other=logs.addRoll("Other roll","Gold 200","",200,36);for(int i=0;i<6;i++)shots.add(logs.insert(owner,System.currentTimeMillis()+i*1000,0,480,"denied","8","1/125","50mm","native "+i,"",""));SQLiteDatabase db=logs.getWritableDatabase();referenceId=UUID.randomUUID().toString();File ref=jpeg(c,referenceId,Color.BLUE);db.execSQL("INSERT INTO reference_photos(id,shot_id,sha256,byte_count,created_at) VALUES(?,?,?,?,?)",new Object[]{referenceId,shots.get(2),"ref-fixture",ref.length(),System.currentTimeMillis()});scanId=UUID.randomUUID().toString();File scan=jpeg(c,scanId,Color.RED);db.execSQL("INSERT INTO scans(id,roll_id,display_name,sha256,byte_count,created_at,shot_id) VALUES(?,?,?,?,?,?,?)",new Object[]{scanId,owner,"Native scan","scan-fixture",scan.length(),System.currentTimeMillis(),shots.get(2)});CatalogStore.Batch b=new CatalogStore.Batch();b.id="";b.stock="Kodak Gold 200";b.iso=200;b.capacity=36;b.format="35 mm";b.quantity=2;b.threshold=1;b.location="冰箱";b.temperature="";b.purchaseDate="";b.expiry="2027-12-31";b.price="30";b.currency="CNY";b.notes="";batch=cat.saveBatch(b,0);logs.costs(owner,"30","20","CNY");logs.costs(other,"10","","USD");}
    private void configure(boolean dark,int width,float scale)throws Exception{main(()->{Configuration config=new Configuration(original);config.uiMode=(config.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|(dark?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO);config.fontScale=scale;config.screenWidthDp=width;activity.getResources().updateConfiguration(config,activity.getResources().getDisplayMetrics());call("render");View root=root();root.getLayoutParams().width=Math.round(width*activity.getResources().getDisplayMetrics().density);root.requestLayout();});}
    private void detailChecks()throws Exception{start(StockDetailActivity.class,new Intent().putExtra("stock","original:kodak_portra_400"));for(boolean dark:new boolean[]{false,true})for(int width:new int[]{320,375,414,768}){configure(dark,width,width==320?1.6f:1f);main(()->{TextView model=(TextView)tag("stock-model"),intro=(TextView)tag("stock-description");float density=activity.getResources().getDisplayMetrics().density;check(Math.abs(model.getTextSize()-android.util.TypedValue.applyDimension(android.util.TypedValue.COMPLEX_UNIT_SP,30,activity.getResources().getDisplayMetrics()))<.2,"model30sp");View facts=tag("stock-facts"),watermark=tag("film-brand-watermark");check(((ViewGroup)facts).getChildCount()==10,"five aligned fields with dividers");check(Math.abs(watermark.getAlpha()-.05f)<.001,"5 percent logo");check(intro.getMaxLines()==Integer.MAX_VALUE,"description expanded");check(Math.abs(intro.getLineHeight()-android.util.TypedValue.applyDimension(android.util.TypedValue.COMPLEX_UNIT_SP,27.75f,activity.getResources().getDisplayMetrics()))<1.5,"native paragraph line height");check(Math.abs(intro.getLeft()-facts.getLeft())<2&&Math.abs(intro.getRight()-facts.getRight())<2,"parameter and paragraph bounds equal");check(Math.abs(intro.getLeft()/density-32)<1,"paragraph 32dp inset");check(intro.getJustificationMode()==android.text.Layout.JUSTIFICATION_MODE_INTER_WORD,"justified paragraph");});}configure(false,original.screenWidthDp,1);snap("01-stock-detail-light");main(()->{ScrollView scroll=(ScrollView)tag("stock-detail-scroll");View logo=tag("film-brand-watermark");int[] before=new int[2];logo.getLocationOnScreen(before);scroll.scrollTo(0,scroll.getChildAt(0).getHeight());scroll.post(()->{});int[] after=new int[2];logo.getLocationOnScreen(after);check(Arrays.equals(before,after)&&scroll.getScrollY()>0,"logo fixed during actual scroll");});configure(true,original.screenWidthDp,1);snap("02-stock-detail-dark");}
    private void libraryChecks()throws Exception{start(StockLibraryActivity.class,new Intent());main(()->{set(activity,"query","Portra 400");set(activity,"brandFilter","Kodak");set(activity,"formatFilter","120");call("render");call("filters");});snap("03-stock-filter");main(()->{Dialog d=sheet();button(d.getWindow().getDecorView(),"重置").performClick();d.cancel();check(field(activity,"brandFilter").equals("Kodak")&&field(activity,"formatFilter").equals("120"),"filter reset cancelled retains applied values");set(activity,"brandFilter","");set(activity,"formatFilter","");call("render");});for(boolean dark:new boolean[]{false,true}){configure(dark,original.screenWidthDp,1);snap(dark?"05-stock-library-dark":"04-stock-library-light");}}
    private void catalogChecks()throws Exception{start(CatalogActivity.class,new Intent().putExtra("tab","gear"));for(boolean dark:new boolean[]{false,true})for(int width:new int[]{320,375,414,768}){configure(dark,width,width==320?1.6f:1f);main(()->{View row=tag("gear-row:"+camera);check(row.getHeight()>=Math.round(88*activity.getResources().getDisplayMetrics().density),"one gear row with loaded metadata");});}configure(false,original.screenWidthDp,1);snap("06-gear-light");configure(true,original.screenWidthDp,1);snap("07-gear-dark");main(()->{call(activity,"gearInfo",new Class<?>[]{CatalogStore.Entry.class},new CatalogStore(logs).entry(camera,"camera"));});snap("08-gear-info");Activity gearPage=activity;Configuration gearConfig=original;ActivityMonitor monitor=addMonitor(MainActivity.class.getName(),null,false);main(()->button(sheet().getWindow().getDecorView(),logs.roll(owner).stock+" · 6/36 ›").performClick());Activity opened=monitor.waitForActivityWithTimeout(5000);removeMonitor(monitor);check(opened instanceof MainActivity,"current roll opens native details");activity=opened;original=new Configuration(opened.getResources().getConfiguration());main(()->activity.onBackPressed());activity=gearPage;original=gearConfig;main(()->check(!activity.isFinishing()&&root().findViewWithTag("gear-row:"+camera)!=null,"back restores equipment page"));start(CatalogActivity.class,new Intent().putExtra("tab","stock"));main(()->{call(activity,"load",new Class<?>[]{String.class},batch);});main(()->{check(new CatalogStore(logs).batch(batch).quantity==2,"opening load no deduction");((EditText)((java.util.ArrayList<?>)field(activity,"fields")).get(0)).getRootView().findViewById(android.R.id.button2).performClick();});main(()->check(new CatalogStore(logs).batch(batch).quantity==2,"cancel load no deduction"));start(CatalogActivity.class,new Intent().putExtra("tab","stock"));snap("09-inventory-light");configure(true,original.screenWidthDp,1);snap("10-inventory-dark");main(()->{call("libraryFilters");sheet().cancel();check(field(activity,"stockAttention").equals(""),"inventory filter cancel unchanged");});}
    private void statsChecks()throws Exception{logs.getWritableDatabase().execSQL("UPDATE rolls SET state='received' WHERE id=?",new Object[]{other});check(StatsStore.read(logs,0,false).rolls==1&&StatsStore.read(logs,0,true).rolls==2,"received rolls follow archive scope");logs.getWritableDatabase().execSQL("UPDATE rolls SET state='active' WHERE id=?",new Object[]{other});start(StatsActivity.class,new Intent());configure(false,original.screenWidthDp,1);snap("11-stats-light");main(()->{set(activity,"year",2025);set(activity,"feesTab",true);call("render");});snap("12-fees-light");main(()->check((Boolean)field(activity,"feesTab")&&(Integer)field(activity,"year")==2025,"fees preserve shooting year"));configure(true,original.screenWidthDp,1);snap("13-fees-dark");main(()->{set(activity,"feesTab",false);set(activity,"year",0);call("render");});snap("14-stats-dark");}
    private void deleteChecks(Context c)throws Exception{start(MainActivity.class,new Intent().putExtra("open_roll",owner));main(()->{check(root().findViewWithTag("exposure-thumb:"+shots.get(2))!=null,"thumbnail per row");Map<String,File> pictures=ContactSheet.photos(activity,(LogStore)field(activity,"store"),owner);check(pictures.get(shots.get(2)).getName().equals(scanId+".jpg"),"scan wins over reference");set(activity,"shotId",shots.get(2));set(activity,"screen","detail");call("render");tag("delete-exposure").performClick();check(logs.roll(owner).count==6,"first tap only confirms");});snap("15-delete-confirm");main(()->{sheet().cancel();check(logs.roll(owner).count==6,"cancel preserves record");tag("delete-exposure").performClick();logs.getWritableDatabase().execSQL("CREATE TRIGGER test_block_delete BEFORE DELETE ON shots BEGIN SELECT RAISE(ABORT,'test deletion failure'); END");sheet().getWindow().getDecorView().findViewWithTag("confirm-delete-exposure").performClick();check(sheet().isShowing()&&logs.roll(owner).count==6,"real SQL failure retains confirmation");check(ReferencePhotos.forShot(logs,shots.get(2)).equals(referenceId)&&new ScanStore(c,logs).list(owner).get(0).shotId.equals(shots.get(2)),"failure rolls back photo links");logs.getWritableDatabase().execSQL("DROP TRIGGER test_block_delete");sheet().getWindow().getDecorView().findViewWithTag("confirm-delete-exposure").performClick();check(logs.roll(owner).count==5&&logs.roll(other).count==0,"retry removes only target");check(logs.nextFrame(owner)==7&&logs.shot(shots.get(3)).frame==4,"remaining frames not renumbered");check(new ScanStore(c,logs).list(owner).get(0).shotId.isEmpty(),"scan kept but detached");check(new ScanStore(c,logs).file(scanId).isFile()&&!new ScanStore(c,logs).file(referenceId).exists(),"private reference removed and scan retained");check(StatsStore.read(logs,0,true).frames==5,"statistics refreshed after delete");try{logs.deleteShot(shots.get(0),other,1);throw new AssertionError("wrong owner accepted");}catch(IllegalArgumentException expected){}check(logs.roll(owner).count==5,"wrong owner no changes");});snap("16-exposure-list-after-delete");}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle out=new Bundle();Context base=getTargetContext();String previous=Workspace.current(base);boolean success=false;try{check(base.getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolated package only");Workspace.activate(base,UUID.randomUUID().toString());Context context=Workspace.context(base);fixture(context);CatalogStore.Batch expiry=new CatalogStore(logs).batch(batch);java.time.LocalDate today=java.time.LocalDate.now();expiry.expiry=today.plusDays(90).toString();check(CatalogStore.expiring(expiry,today),"existing 90-day alert boundary");expiry.expiry=today.plusDays(91).toString();check(!CatalogStore.expiring(expiry,today),"outside 90-day alert");expiry.expiry=today.toString();expiry.quantity=0;check(!CatalogStore.expiring(expiry,today),"depleted batch not expiry alert");check(FilmDetails.production(context,"original:kodak_portra_400").equals("在产"),"existing production metadata");check(FilmDetails.production(context,"custom:unknown").equals("未知"),"unknown not false");detailChecks();libraryChecks();catalogChecks();statsChecks();deleteChecks(context);out.putString("stream","PASS: "+assertions+" assertions; native stock detail five dimensions, 30sp model, 15sp full intro, equal32dp bounds and fixed5% logo; library filters; unique equipment rows/current roll; inventory cancel no deduction; shooting/fees independent years; native thumbnail scan priority; delete confirm/cancel, real SQL rollback/retry, owner isolation, reference cleanup and preserved scan/frames; dual themes/widths with synthetic native screenshots.\n");success=true;}catch(Throwable e){out.putString("stream",android.util.Log.getStackTraceString(e));}finally{try{if(activity!=null)main(()->{activity.getResources().updateConfiguration(original,activity.getResources().getDisplayMetrics());activity.finish();});}catch(Exception ignored){}if(logs!=null)logs.close();Workspace.activate(base,previous);}finish(success?-1:0,out);}
}
